//! 費用付き修復順位の独立診断。解だけを元問題で検査して返す。
use mip_codex::{heuristic::Repair,solve::Result};
fn main(){let a:Vec<_>=std::env::args().collect();if a.get(1).is_some_and(|v|v=="build-info"){println!("{}",serde_json::json!({"source_directory":env!("CARGO_MANIFEST_DIR"),"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT,"library_source_directory":mip_codex::BUILD_SOURCE_DIRECTORY,"library_source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));return;}let m=mip_codex::mps::read(&a[1]).unwrap();let input:serde_json::Value=serde_json::from_reader(std::fs::File::open(&a[2]).unwrap()).unwrap();let seed:Vec<_>=m.variables.iter().map(|v|input["values"][&v.name].as_f64().unwrap()).collect();let mut repair=Repair::new(&m);assert!(repair.candidate_check(&seed));let lower:Vec<_>=m.variables.iter().map(|v|v.lower).collect();let upper:Vec<_>=m.variables.iter().map(|v|v.upper).collect();let start:Vec<_>=lower.iter().zip(&upper).map(|(l,u)|0f64.max(l.unwrap_or(f64::NEG_INFINITY)).min(u.unwrap_or(f64::INFINITY))).collect();let sign=if m.maximize{-1.}else{1.};let mut costs:Vec<_>=m.variables.iter().map(|v|sign*v.objective).filter(|v|v.is_finite()&&*v>0.).collect();costs.sort_by(f64::total_cmp);let scale=costs.get(costs.len()/2).copied().unwrap_or(1.);let seconds:f64=a[3].parse().unwrap();let weight:f64=a[4].parse().unwrap();let began=std::time::Instant::now();let end=began+std::time::Duration::from_secs_f64(seconds);let candidate=repair.search_priced(&start,&lower,&upper,end,100_000_000,0,weight,scale);let found=candidate.is_some();let x=candidate.filter(|v|repair.candidate_check(v)&&m.objective(v).is_finite()&&sign*m.objective(v)<sign*m.objective(&seed)).unwrap_or(seed);let result=Result{status:"feasible_priced_repair_diagnostic".into(),objective:Some(m.objective(&x)),values:Some(m.variables.iter().zip(x).map(|(v,x)|(v.name.clone(),x)).collect()),seconds:began.elapsed().as_secs_f64(),..Result::default()};serde_json::to_writer(std::fs::File::create(&a[5]).unwrap(),&result).unwrap();println!("{}",serde_json::json!({"objective":result.objective,"found":found,"weight":weight,"scale":scale,"seconds":result.seconds,"work":repair.stats.work,"moves":repair.stats.moves,"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));}
